import type { QueryClient } from "@tanstack/react-query";
import { apiClient } from "./client";

/** Refresh Feedback moderation list/summary after a user submits vote feedback. */
export function invalidateFeedbackModeration(queryClient: QueryClient): void {
  void queryClient.invalidateQueries({ queryKey: ["feedbackModerationEntries"] });
  void queryClient.invalidateQueries({ queryKey: ["feedbackModerationSummary"] });
}

export type FeedbackModerationRow = {
  id: string;
  message_id: string;
  session_id: string;
  user_id: number | null;
  user_message: string;
  assistant_preview: string;
  assistant_response_length: number;
  feedback: boolean;
  feedback_rating: number | null;
  feedback_text: string | null;
  context_tags: string[] | null;
  message_type: string;
  created_at: string;
  confidence_score: number | null;
  total_ms: number | null;
  llm_model: string | null;
  embedding_model: string | null;
  feedback_moderation: Record<string, unknown> | null;
};

export type FeedbackModerationSummary = {
  total_count: number;
  positive_count: number;
  negative_count: number;
  positive_pct: number;
  negative_pct: number;
  avg_total_ms: number | null;
  top_negative_reasons: { key: string; count: number }[];
  low_confidence_negative_count: number;
  flagged_count: number;
  reviewed_count: number;
};

export type FeedbackExportParams = {
  messageType?: string;
  q?: string;
  feedback?: boolean;
  maxRows?: number;
  session_id?: string;
  user_id?: number;
  reason?: string;
  date_from?: string;
  date_to?: string;
  reviewed?: boolean;
  flagged?: boolean;
  min_confidence?: number;
  max_confidence?: number;
  min_total_ms?: number;
  max_total_ms?: number;
  llm_model?: string;
  source_contains?: string;
};

export type ReasonCatalog = {
  positive: { key: string; labelKey: string }[];
  negative: { key: string; labelKey: string }[];
  legacy: string[];
};

export const feedbackModerationAPI = {
  getReasonCatalog: async (): Promise<ReasonCatalog> => {
    const { data } = await apiClient.get<ReasonCatalog>("/feedback/reason-catalog");
    return data;
  },

  getEntries: async (params?: Record<string, string | number | boolean | undefined>): Promise<FeedbackModerationRow[]> => {
    const { data } = await apiClient.get<FeedbackModerationRow[]>("/feedback/moderation/entries", {
      params: Object.fromEntries(
        Object.entries(params ?? {}).filter(([, v]) => v !== undefined && v !== "")
      ),
    });
    return data;
  },

  getSummary: async (messageType = "all"): Promise<FeedbackModerationSummary> => {
    const { data } = await apiClient.get<FeedbackModerationSummary>("/feedback/moderation/summary", {
      params: { message_type: messageType },
    });
    return data;
  },

  patchModeration: async (
    messageId: string,
    body: { reviewed?: boolean; internal_notes?: string; flagged?: boolean; flag_reason?: string }
  ): Promise<{ success: boolean; feedback_moderation: Record<string, unknown> | null }> => {
    const { data } = await apiClient.patch<{ success: boolean; feedback_moderation: Record<string, unknown> | null }>(
      `/feedback/moderation/${messageId}`,
      body
    );
    return data;
  },

  exportBlob: async (fmt: "csv" | "json", opts?: FeedbackExportParams): Promise<Blob> => {
    const params: Record<string, string | number | boolean | undefined> = {
      fmt,
      message_type: opts?.messageType ?? "all",
      max_rows: opts?.maxRows ?? 10_000,
      q: opts?.q || undefined,
      feedback: opts?.feedback,
      session_id: opts?.session_id,
      user_id: opts?.user_id,
      reason: opts?.reason,
      date_from: opts?.date_from,
      date_to: opts?.date_to,
      reviewed: opts?.reviewed,
      flagged: opts?.flagged,
      min_confidence: opts?.min_confidence,
      max_confidence: opts?.max_confidence,
      min_total_ms: opts?.min_total_ms,
      max_total_ms: opts?.max_total_ms,
      llm_model: opts?.llm_model,
      source_contains: opts?.source_contains,
    };
    const { data } = await apiClient.get("/feedback/moderation/export", {
      params: Object.fromEntries(
        Object.entries(params).filter(([, v]) => v !== undefined && v !== "")
      ),
      responseType: "blob",
    });
    return data as Blob;
  },
};
