import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useState, useEffect } from 'react';
import { authAPI, LoginCredentials, LoginResponse, User } from '@/services/api/api';
import { hasStoredAuthSession, writeAuthTokenExpires } from '@/lib/authSession';
import { isPublicAuthPath } from '@/constants/routes';

export const useAuth = () => {
  const queryClient = useQueryClient();

  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isVerifyingToken, setIsVerifyingToken] = useState<boolean>(false);
  
  const [requires2FA, setRequires2FA] = useState<boolean>(false);
  const [temp2FAToken, setTemp2FAToken] = useState<string | null>(null);

  const isWidgetMode = typeof window !== 'undefined' && !!(window as any).RAGSUITE_PROJECT_ID;
  const projectId = isWidgetMode ? (window as any).RAGSUITE_PROJECT_ID : null;

  useEffect(() => {
    const syncAuthState = () => {
      const currentUser = getCurrentUser();

      const tempToken = localStorage.getItem('temp_2fa_token');
      if (tempToken && !hasStoredAuthSession()) {
        setRequires2FA(true);
        setTemp2FAToken(tempToken);
      } else {
        setRequires2FA(false);
        setTemp2FAToken(null);
      }
      
      const isAuth = isWidgetMode ? !!projectId : hasStoredAuthSession();

      setUser(currentUser);
      setToken(null);
      setIsAuthenticated(isAuth);
    };

    syncAuthState();

    const handleStorageChange = (e: StorageEvent) => {
      if (
        e.key === 'auth_token' ||
        e.key === 'auth-token' ||
        e.key === 'user_data' ||
        e.key === 'token_expires'
      ) {
        syncAuthState();
      }
    };

    const handleEmailVerifiedMessage = (e: MessageEvent) => {
      if (e.origin !== window.location.origin) return;
      if (e.data?.type === 'ragsuite:email-verified') {
        syncAuthState();
      }
    };

    const handleTokenUpdate = (e: CustomEvent) => {
      syncAuthState();
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('message', handleEmailVerifiedMessage);
    window.addEventListener('auth-token-updated', handleTokenUpdate as EventListener);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('message', handleEmailVerifiedMessage);
      window.removeEventListener('auth-token-updated', handleTokenUpdate as EventListener);
    };
  }, [isWidgetMode, projectId]);

  useEffect(() => {
    if (isWidgetMode) {
      return;
    }

    if (!hasStoredAuthSession()) {
      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
      return;
    }

    const verifyTokenOnStartup = async () => {
      setIsVerifyingToken(true);
      try {
        await authAPI.verifyToken();
      } catch (error: any) {
        console.warn('🔐 Token verification failed on startup:', error);

        const isUnauthorized = error?.response?.status === 401;
        const errorDetail = error?.response?.data?.detail || '';
        const errorDetailLower = typeof errorDetail === 'string' ? errorDetail.toLowerCase() : '';

        const isInactivityTimeout = errorDetailLower.includes('session expired due to inactivity');
        const isSessionRevoked = errorDetailLower.includes('session has been revoked');
        const isSessionExpired = errorDetailLower.includes('session expired');

        if (isUnauthorized && (isInactivityTimeout || isSessionRevoked || isSessionExpired || !errorDetail)) {
          console.warn('🔐 Session expired or inactive - clearing auth and redirecting to login');

          localStorage.removeItem('auth-user');
          localStorage.removeItem('user_data');
          localStorage.removeItem('token_expires');

          setUser(null);
          setToken(null);
          setIsAuthenticated(false);

          queryClient.clear();

          if (
            typeof window !== 'undefined' &&
            !isPublicAuthPath(window.location.pathname)
          ) {
            window.location.href = '/login';
          }
        } else {
          console.warn('🔐 Token verification error (non-auth):', error);
        }
      } finally {
        setIsVerifyingToken(false);
      }
    };

    verifyTokenOnStartup();
  }, []);

  const loginMutation = useMutation({
    mutationFn: (credentials: LoginCredentials) => {
      localStorage.removeItem('temp_2fa_token');
      setTemp2FAToken(null);
      setRequires2FA(false);
      return authAPI.login(credentials);
    },

    onSuccess: (data: LoginResponse) => {

      if (data.requires_2fa) {
        if (data.temp_token) {
          localStorage.removeItem('temp_2fa_token');
          localStorage.setItem('temp_2fa_token', data.temp_token);
          setTemp2FAToken(data.temp_token);
          setRequires2FA(true);
        }
        return;
      }
      
      setRequires2FA(false);
      setTemp2FAToken(null);
      localStorage.removeItem('temp_2fa_token');

      if (!data.access_token || !data.user) {
        console.error('❌ Login response missing required fields:', data);
        return;
      }

      localStorage.setItem('user_data', JSON.stringify(data.user));
      writeAuthTokenExpires();

      const userWithCreatedAt: User = {
        id: String(data.user.id),
        username: data.user.username,
        email: data.user.email,
        role: data.user.is_admin ? 'admin' : 'user',
        permissions: data.user.is_admin ? ['read', 'write', 'admin'] : ['read', 'write'],
        createdAt: data.user.created_at || new Date().toISOString(),
        lastLogin: data.user.last_login || undefined
      };
      setUser(userWithCreatedAt);
      setToken(null);
      setIsAuthenticated(true);

      queryClient.invalidateQueries({ queryKey: ['auth-user'] });

      queryClient.invalidateQueries({ queryKey: ['settings'] });

    },

    onError: (error) => {
      console.error('❌ Login failed:', error);
      localStorage.removeItem('user_data');
      localStorage.removeItem('token_expires');
      localStorage.removeItem('temp_2fa_token');

      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
      setRequires2FA(false);
      setTemp2FAToken(null);
    },
  });
  
  const verify2FALoginMutation = useMutation({
    mutationFn: async (code: string) => {
      const tempToken = temp2FAToken || localStorage.getItem('temp_2fa_token');
      if (!tempToken) {
        throw new Error('No temporary token found. Please log in again.');
      }
      return await authAPI.verifyLogin2FA(tempToken, code);
    },
    
    onSuccess: (data) => {
      if (data.access_token && data.user) {
        localStorage.setItem('user_data', JSON.stringify(data.user));
        writeAuthTokenExpires();

        const userWithCreatedAt: User = {
          id: String(data.user.id),
          username: data.user.username,
          email: data.user.email,
          role: data.user.is_admin ? 'admin' : 'user',
          permissions: data.user.is_admin ? ['read', 'write', 'admin'] : ['read', 'write'],
          createdAt: data.user.created_at || new Date().toISOString(),
          lastLogin: data.user.last_login || undefined
        };
        
        setUser(userWithCreatedAt);
        setToken(null);
        setIsAuthenticated(true);

        queryClient.invalidateQueries({ queryKey: ['auth-user'] });
        queryClient.invalidateQueries({ queryKey: ['settings'] });
      }

      // Clear 2FA state after auth is set so the login form does not flash.
      setRequires2FA(false);
      setTemp2FAToken(null);
      localStorage.removeItem('temp_2fa_token');
    },
    
    onError: (error: any) => {
      console.error('❌ 2FA verification failed:', error);
      
      const errorResponse = error?.response;
      const errorData = errorResponse?.data;
      const errorDetail = errorData?.detail || '';
      const statusCode = errorResponse?.status;
      
      console.error('🔐 2FA Error Details:', {
        status: statusCode,
        detail: errorDetail,
        message: error?.message,
        fullError: error
      });
      
      if (errorDetail.includes('expired') || 
          errorDetail.includes('Invalid temporary token') ||
          errorDetail.includes('Invalid or expired temporary token') ||
          errorDetail.includes('Temporary token has expired')) {
        console.warn('🔐 Temp token expired - clearing 2FA state');
        setRequires2FA(false);
        setTemp2FAToken(null);
        localStorage.removeItem('temp_2fa_token');
      } else if (errorDetail.includes('Invalid 2FA code') || errorDetail.includes('TOTP') || errorDetail.includes('sign-in code')) {
        console.warn('🔐 Invalid 2FA code - keeping 2FA state for retry');
      } else {
        console.warn('🔐 Unknown 2FA error - keeping 2FA state');
      }
    },
  });

  const resendLogin2FAMutation = useMutation({
    mutationFn: async () => {
      const tempToken = temp2FAToken || localStorage.getItem('temp_2fa_token');
      if (!tempToken) {
        throw new Error('No temporary token found. Please log in again.');
      }
      return await authAPI.resendLogin2FA(tempToken);
    },
  });

  const logoutMutation = useMutation({
    mutationFn: () => authAPI.logout(),

    onSuccess: () => {
      localStorage.removeItem('auth-user');
      localStorage.removeItem('user_data');
      localStorage.removeItem('token_expires');
      localStorage.removeItem('temp_2fa_token');

      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
      setRequires2FA(false);
      setTemp2FAToken(null);

      queryClient.clear();
    },

    onError: (error) => {
      console.error('❌ Logout failed:', error);
      localStorage.removeItem('auth-user');
      localStorage.removeItem('user_data');
      localStorage.removeItem('token_expires');
      localStorage.removeItem('temp_2fa_token');

      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
      setRequires2FA(false);
      setTemp2FAToken(null);

      queryClient.clear();
    },
  });

  const getCurrentUser = (): User | null => {
    try {
      const isWidgetMode = typeof window !== 'undefined' && !!(window as any).RAGSUITE_PROJECT_ID;
      
      if (isWidgetMode) {
        return null; // Return null but don't log "No valid user data" in widget mode
      }

      if (!hasStoredAuthSession()) {
        return null;
      }

      const userData = localStorage.getItem('user_data');
      if (!userData) {
        return null;
      }

      const user = JSON.parse(userData);
      return user;
    } catch (error) {
      console.error('❌ Error parsing user data:', error);
      localStorage.removeItem('user_data');
      localStorage.removeItem('token_expires');
      return null;
    }
  };

  return {
    login: loginMutation.mutate,
    loginAsync: loginMutation.mutateAsync,
    isLoggingIn: loginMutation.isPending,
    loginError: loginMutation.error,
    loginData: loginMutation.data,

    logout: logoutMutation.mutate,
    logoutAsync: logoutMutation.mutateAsync,
    isLoggingOut: logoutMutation.isPending,
    logoutError: logoutMutation.error,

    isAuthenticated: isAuthenticated,
    user,
    token,
    isVerifyingToken,

    requires2FA,
    temp2FAToken,
    verifyLogin2FA: verify2FALoginMutation.mutate,
    verifyLogin2FAAsync: verify2FALoginMutation.mutateAsync,
    isVerifying2FA: verify2FALoginMutation.isPending,
    verify2FAError: verify2FALoginMutation.error,
    resendLogin2FA: resendLogin2FAMutation.mutate,
    isResendingLogin2FA: resendLogin2FAMutation.isPending,
    resendLogin2FAError: resendLogin2FAMutation.error,
    clear2FA: () => {
      setRequires2FA(false);
      setTemp2FAToken(null);
      localStorage.removeItem('temp_2fa_token');
      loginMutation.reset();
    },

    resetLogin: loginMutation.reset,
  };
};

export const useTokenVerification = () => {
  const hasSession = hasStoredAuthSession();

  const verificationQuery = useQuery({
    queryKey: ['auth-verify'],
    queryFn: () => authAPI.verifyToken(),
    enabled: hasSession,
    retry: false,
    staleTime: 5 * 60 * 1000,
  });

  return {
    isVerifying: verificationQuery.isLoading,
    isTokenValid: verificationQuery.isSuccess,
    verificationError: verificationQuery.error,
    refetch: verificationQuery.refetch,
  };
};
