import * as React from "react";
import { useCallback } from "react";
import { Badge } from "@/components/ui/badge";
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "@/components/ui/HoverCard";
import { useToast } from "@/hooks/useToast";
import { simpleHighlight } from "@/utils/textHighlighting";
import {
  CitationFormattingOptions,
  DEFAULT_CITATION_FORMATTING,
} from "@/contexts/CitationFormattingContext";
import {
  isAuthenticatedDocumentContentUrl,
  openCitationSourceUrl,
} from "@/utils/openCitationSource";

export interface CitationSource {
  title: string;
  url: string;
  snippet: string;
}

export function normalizeCitationSnippet(snippet?: string | null): string {
  const value = (snippet ?? "").trim();
  if (!value || value === "No snippet available") {
    return "";
  }
  return value;
}

export function normalizeCitationNumbering(
  raw: string | undefined,
): CitationFormattingOptions["numbering"] {
  if (!raw) return "brackets";
  const lower = raw.toLowerCase().trim();
  if (lower === "brackets" || raw.includes("[")) return "brackets";
  if (lower === "parentheses" || raw.includes("(")) return "parentheses";
  if (lower === "dots" || /\d\.\s*\d/.test(raw)) return "dots";
  if (lower === "numbers") return "numbers";
  return "brackets";
}

export function resolveCitationFormatting(
  formatting?: Partial<CitationFormattingOptions> | null,
): CitationFormattingOptions {
  if (!formatting) return DEFAULT_CITATION_FORMATTING;
  return {
    ...DEFAULT_CITATION_FORMATTING,
    ...formatting,
    numbering: normalizeCitationNumbering(formatting.numbering),
  };
}

interface CitationSourcesListProps {
  citations: CitationSource[];
  formatting?: Partial<CitationFormattingOptions> | null;
  actualTopK?: number;
  ragSettingsTopK?: number;
  queryString?: string;
  showTopKInHeader?: boolean;
  className?: string;
}

export function CitationSourcesList({
  citations,
  formatting: formattingProp,
  actualTopK,
  ragSettingsTopK,
  queryString,
  showTopKInHeader = false,
  className = "space-y-3 pt-3 border-t border-border/20 overflow-x-hidden",
}: CitationSourcesListProps) {
  const formatting = resolveCitationFormatting(formattingProp);
  const { toast } = useToast();

  const handleCitationSourceClick = useCallback(
    async (e: React.MouseEvent<HTMLAnchorElement>, url: string) => {
      if (!isAuthenticatedDocumentContentUrl(url)) return;
      e.preventDefault();
      try {
        await openCitationSourceUrl(url);
      } catch (err: unknown) {
        const ax = err as { response?: { data?: { detail?: string } } };
        const detail = ax.response?.data?.detail;
        toast({
          title: "Could not open source",
          description:
            typeof detail === "string"
              ? detail
              : err instanceof Error
                ? err.message
                : "Request failed",
          variant: "destructive",
        });
      }
    },
    [toast],
  );

  if (!citations.length) return null;

  const topKValue =
    actualTopK !== undefined
      ? actualTopK
      : ragSettingsTopK !== undefined
        ? ragSettingsTopK
        : citations.length;
  const dedupedCitations = React.useMemo(() => {
    const seen = new Set<string>();
    const output: CitationSource[] = [];
    for (const source of citations) {
      const title = String(source?.title || "").trim().toLowerCase();
      const url = String(source?.url || "").trim().toLowerCase().replace(/\/+$/, "");
      const key = url || `title:${title}`;
      if (!key) continue;
      if (seen.has(key)) continue;
      seen.add(key);
      output.push(source);
    }
    return output;
  }, [citations]);

  const displayedCitations = topKValue
    ? dedupedCitations.slice(0, Math.min(topKValue, dedupedCitations.length))
    : dedupedCitations;

  const getNumberingStyle = (index: number) => {
    switch (formatting.numbering) {
      case "brackets":
        return `[${index + 1}]`;
      case "parentheses":
        return `(${index + 1})`;
      case "dots":
        return `${index + 1}.`;
      case "numbers":
        return `${index + 1}`;
      default:
        return `[${index + 1}]`;
    }
  };

  const getCitationStyleClasses = () => {
    const baseClasses = "rounded-md border w-full min-w-0";
    switch (formatting.style) {
      case "compact":
        return `${baseClasses} p-1 text-xs`;
      case "detailed":
        return `${baseClasses} p-3 bg-muted/50`;
      case "card":
        return `${baseClasses} p-2 shadow-sm`;
      case "minimal":
        return `${baseClasses} p-1 text-xs bg-transparent border-dashed`;
      default:
        return `${baseClasses} p-2`;
    }
  };

  const getLayoutClasses = () => {
    switch (formatting.layout) {
      case "grid":
        return "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 items-stretch";
      case "vertical":
      default:
        return "space-y-2";
    }
  };

  const getColorSchemeClasses = () => {
    switch (formatting.colorScheme) {
      case "primary":
        return "border-primary/20 bg-primary/5";
      case "muted":
        return "border-muted bg-muted/30";
      case "accent":
        return "border-accent/20 bg-accent/5";
      default:
        return "border-border/20 bg-muted/30";
    }
  };

  const truncateSnippet = (snippet: string) => {
    if (!formatting.showSnippets) return "";
    if (snippet.length <= formatting.maxSnippetLength) return snippet;
    return snippet.substring(0, formatting.maxSnippetLength) + "...";
  };

  const renderCitationCard = (source: CitationSource, index: number) => {
    const hoverClasses = formatting.enableHover
      ? "cursor-pointer transition-all duration-200 ease-in-out hover:scale-[1.02] hover:shadow-md hover:border-primary/30"
      : "";
    const heightClasses = formatting.layout === "grid" ? "h-full flex flex-col" : "";
    const snippet = truncateSnippet(normalizeCitationSnippet(source.snippet));

    return (
      <div
        className={`${getCitationStyleClasses()} ${getColorSchemeClasses()} ${hoverClasses} ${heightClasses}`}
        data-rag-citation-card="true"
      >
        <div className={`flex items-start gap-2 ${formatting.layout === "grid" ? "flex-1" : ""}`}>
          <Badge
            variant="outline"
            className={`text-xs shrink-0 ${formatting.style === "minimal" ? "text-xs px-1 py-0" : ""}`}
          >
            {getNumberingStyle(index)}
          </Badge>
          <div className="flex-1 min-w-0 flex flex-col">
            <p
              className={`font-medium text-foreground mb-1 break-words overflow-wrap-anywhere ${
                formatting.style === "compact" ? "text-xs" : "text-sm"
              }`}
              data-rag-citation-title="true"
            >
              {source.title || `Source ${index + 1}`}
            </p>
            {formatting.showSnippets && snippet && (
              <p
                className={`text-muted-foreground leading-relaxed flex-1 break-words overflow-wrap-anywhere ${
                  formatting.style === "compact" ? "text-xs" : "text-xs"
                }`}
                data-rag-citation-snippet="true"
              >
                {queryString ? simpleHighlight(snippet, queryString) : snippet}
              </p>
            )}
            {formatting.showUrls && source.url && source.url !== "#" && (
              <a
                href={
                  isAuthenticatedDocumentContentUrl(source.url) ? "#" : source.url
                }
                onClick={(e) => void handleCitationSourceClick(e, source.url)}
                target="_blank"
                rel="noopener noreferrer"
                className={`text-primary hover:underline mt-1 inline-block break-all ${
                  formatting.style === "compact" ? "text-xs" : "text-xs"
                }`}
                data-rag-citation-link="true"
              >
                View Source →
              </a>
            )}
          </div>
        </div>
      </div>
    );
  };

  const renderHoverCardContent = (source: CitationSource, index: number) => (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <Badge variant="outline" className="text-xs">
          {getNumberingStyle(index)}
        </Badge>
        <h4 className="font-semibold text-sm">{source.title || `Source ${index + 1}`}</h4>
      </div>
      {normalizeCitationSnippet(source.snippet) && (
        <p className="text-sm text-muted-foreground leading-relaxed">{source.snippet}</p>
      )}
      {source.url && source.url !== "#" && (
        <div className="pt-2 border-t">
          <a
            href={isAuthenticatedDocumentContentUrl(source.url) ? "#" : source.url}
            onClick={(e) => void handleCitationSourceClick(e, source.url)}
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-primary hover:underline flex items-center gap-1 break-all"
          >
            <span className="truncate">{source.url}</span>
          </a>
        </div>
      )}
    </div>
  );

  return (
    <div className={className}>
      {formatting.showSourceCount && (
        <div className="flex items-center gap-2 flex-wrap">
          {showTopKInHeader && topKValue !== undefined && topKValue !== null && (
            <span className="text-xs font-medium text-muted-foreground">Top-K: {topKValue}</span>
          )}
          <span className="text-xs font-medium text-muted-foreground">
            Sources ({displayedCitations.length}):
          </span>
        </div>
      )}

      <div
        className={`${getLayoutClasses()} overflow-x-hidden w-full min-w-0`}
        data-rag-citation-layout={formatting.layout}
      >
        {displayedCitations.map((source, index) =>
          formatting.enableHover ? (
            <div key={index} className={formatting.layout === "grid" ? "h-full" : ""}>
              <HoverCard openDelay={300} closeDelay={100}>
                <HoverCardTrigger asChild>{renderCitationCard(source, index)}</HoverCardTrigger>
                <HoverCardContent
                  className="w-80 max-h-60 overflow-y-auto"
                  side="top"
                  align="start"
                  sideOffset={5}
                >
                  {renderHoverCardContent(source, index)}
                </HoverCardContent>
              </HoverCard>
            </div>
          ) : (
            <div key={index} className={formatting.layout === "grid" ? "h-full" : ""}>
              {renderCitationCard(source, index)}
            </div>
          ),
        )}
      </div>
    </div>
  );
}
