
import React from "react";
import { createRoot } from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { EmbeddableSearchWidget } from "./components/common/EmbeddableSearchWidget";
import { RAGSettingsProvider } from "./contexts/RAGSettingsContext";
import { BrandingProvider } from "./contexts/BrandingContext";
import { ThemeProvider, useTheme } from "./contexts/ThemeContext";
import { AuthProvider } from "./contexts/AuthContext";
import { CitationFormattingProvider } from "./contexts/CitationFormattingContext";
import { useSearchActivation } from "./hooks/useSearchActivation";
import { getWidgetAssetOrigin, resolveBrowserApiBaseUrl } from "./utils/publicApiBaseUrl";
import "./styles/index.css";
import "./components/common/WidgetTailwindScope.css";
import "./components/common/EmbeddableSearchWidgetStyles.css";

const searchWidgetQueryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      refetchOnMount: true,
      staleTime: 5 * 60 * 1000,
      retry: 1,
    },
    mutations: {
      retry: 1,
    },
  },
});

interface SearchWidgetConfig {
  projectId: string;
  apiEndpoint?: string;
  position?: "bottom-right" | "bottom-left" | "top-right" | "top-left" | "inline" | "fixed" | "center";
  zIndex?: number;
  primaryColor?: string;
  title?: string;
  welcomeMessage?: string;
  orgName?: string;
  searchTitle?: string;
  widgetLogoUrl?: string;
  widgetAvatar?: string;
  widgetShowLogo?: boolean;
  widgetShowDateTime?: boolean;
  widgetBottomSpace?: number;
  widgetFontSize?: number;
  widgetTriggerBorderRadius?: number;
  widgetOffsetX?: number;
  widgetOffsetY?: number;
  insertAfter?: boolean;
  containerSelector?: string | null;

  exclusive?: boolean;
  exclusivePriority?: number;
}

let searchWidgetInstance: {
  root: any;
  container: HTMLElement;
  projectId?: string; // Store project ID per instance to avoid conflicts with RAGSuite website's global project ID
} | null = null;

const getRegistry = (): {
  search?: { priority: number; destroy: () => void };
} => {
  if (!(window as any).__RAGSUITE_WIDGET_REGISTRY__) {
    (window as any).__RAGSUITE_WIDGET_REGISTRY__ = {};
  }
  return (window as any).__RAGSUITE_WIDGET_REGISTRY__;
};

const getSearchWidgetProjectId = (): string | null => {
  if (searchWidgetInstance?.projectId) {
    return searchWidgetInstance.projectId;
  }
  
  const instanceKeys = Object.keys(window).filter(key => 
    key.startsWith('__RAGSUITE_SEARCH_WIDGET_') && key.endsWith('__')
  );
  
  if (instanceKeys.length > 0) {
    let latestInstance: any = null;
    let latestTimestamp = 0;
    
    instanceKeys.forEach(key => {
      const instance = (window as any)[key];
      if (instance && instance.timestamp && instance.timestamp > latestTimestamp) {
        latestTimestamp = instance.timestamp;
        latestInstance = instance;
      }
    });
    
    if (latestInstance?.projectId) {
      return latestInstance.projectId;
    }
  }
  
  return (window as any).RAGSUITE_PROJECT_ID || null;
};

(window as any).__RAGSUITE_GET_SEARCH_WIDGET_PROJECT_ID__ = getSearchWidgetProjectId;

let API_BASE_URL = "";

function initSearchWidget(config: SearchWidgetConfig) {
  if (!config.projectId) {
    console.error("RAG Suite Search Widget: projectId is required. Please provide a valid project ID.");
    return;
  }

  const registry = getRegistry();
  const exclusive = config.exclusive !== false;
  const priority = config.exclusivePriority ?? 0;
  
  if (searchWidgetInstance) {
    const instanceProjectId = searchWidgetInstance.projectId || 
      (window as any).RAGSUITE_PROJECT_ID;
    
    if (instanceProjectId && instanceProjectId !== config.projectId) {
      destroySearchWidget();
    } else if (instanceProjectId === config.projectId) {
      console.warn("RAG Suite Search Widget: Already initialized with same project ID. Use destroy() first to reinitialize.");
      return;
    } else {
      destroySearchWidget();
    }
  }

  if (exclusive && registry.search) {
    if (priority < registry.search.priority) {
      console.warn("RAG Suite Search Widget: Skipping init due to existing search widget with higher priority.");
      return;
    }
    registry.search.destroy();
  }

  API_BASE_URL = resolveBrowserApiBaseUrl(config.apiEndpoint, {
    pageOrigin: window.location.origin,
    assetOrigin: getWidgetAssetOrigin(),
  });

  const getCurrentDomain = (): string | null => {
    try {
      if (typeof window !== 'undefined') {
        const hostname = window.location.hostname;
        return hostname.split(':')[0];
      }
    } catch (e) {
      console.warn('RAG Suite Search Widget: Could not extract domain:', e);
    }
    return null;
  };

  const currentDomain = getCurrentDomain();
  if (currentDomain) {
    (window as any).RAGSUITE_CURRENT_DOMAIN = currentDomain;
  } else {
    console.error('❌ RAG Suite Search Widget: Failed to extract domain!', {
      hostname: typeof window !== 'undefined' ? window.location?.hostname : 'N/A'
    });
  }

  // Always use the canonical search widget CSS endpoint.
  // Do not infer from currentScript because ragsuite-init.js can be the active script.
  const cssUrl = `${API_BASE_URL}/search-widget/v1/search-widget.css`;
  

  const widgetInstanceKey = `__RAGSUITE_SEARCH_WIDGET_${config.projectId}__`;
  (window as any)[widgetInstanceKey] = {
    projectId: config.projectId,
    apiEndpoint: config.apiEndpoint,
    timestamp: Date.now()
  };

  (window as any).RAGSUITE_PROJECT_ID = config.projectId;
  (window as any).RAGSUITE_API_ENDPOINT = API_BASE_URL;

  const hostElement = document.createElement("div");
  hostElement.id = "ragsuite-search-widget-host";
  
  hostElement.style.cssText = `
    all: initial !important;
    display: block !important;
    width: 100% !important;
    height: auto !important;
    position: relative !important;
    z-index: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    box-sizing: border-box !important;
    isolation: isolate !important;
    contain: layout style paint !important;
    visibility: visible !important;
    opacity: 1 !important;
    font-family: inherit !important;
    font-size: inherit !important;
    line-height: inherit !important;
    color: inherit !important;
    text-align: left !important;
    text-decoration: none !important;
    text-transform: none !important;
    letter-spacing: normal !important;
    word-spacing: normal !important;
    white-space: normal !important;
  `;
  
  hostElement.setAttribute('data-ragsuite-widget', 'search');

  const findFooter = (): HTMLElement | null => {
    const footerByTag = document.querySelector('footer');
    if (footerByTag) {
      return footerByTag as HTMLElement;
    }
    
    const footerByClass = document.querySelector('.footer');
    if (footerByClass) {
      return footerByClass as HTMLElement;
    }
    
    const footerById = document.querySelector('#footer');
    if (footerById) {
      return footerById as HTMLElement;
    }
    
    return null;
  };

  const insertWidget = () => {
    const footer = findFooter();
    if (footer && footer.parentNode) {
      footer.parentNode.insertBefore(hostElement, footer);
      return;
    }

  if (config.containerSelector) {
    const targetContainer = document.querySelector(config.containerSelector);
    if (targetContainer) {
        const containerFooter = targetContainer.querySelector('footer, .footer, #footer');
        if (containerFooter && containerFooter.parentNode) {
          containerFooter.parentNode.insertBefore(hostElement, containerFooter);
        } else {
          targetContainer.appendChild(hostElement);
        }
        return;
      }
    }

    if (document.body) {
      const footer = findFooter();
      if (footer && footer.parentNode === document.body) {
        document.body.insertBefore(hostElement, footer);
      } else {
      document.body.appendChild(hostElement);
      }
    } else {
        document.addEventListener('DOMContentLoaded', () => {
        const footer = findFooter();
        if (footer && footer.parentNode === document.body) {
          document.body.insertBefore(hostElement, footer);
        } else if (document.body) {
          document.body.appendChild(hostElement);
        }
        });
    }
  };

  if (document.body) {
    insertWidget();
  } else {
    document.addEventListener('DOMContentLoaded', insertWidget);
  }

  const shadow = hostElement.attachShadow({ 
    mode: 'open',
    delegatesFocus: false
  });
  
  const isolationStyle = document.createElement('style');
  isolationStyle.textContent = `
    /* Prevent any style leakage from Shadow DOM to host page */
    /* NOTE: Don't use 'all: initial' as it resets display to inline */
    /* Instead, explicitly set only the properties we need to reset */
    :host {
      display: block !important;
      contain: layout style paint !important;
      isolation: isolate !important;
      position: relative !important;
      width: 100% !important;
      height: auto !important;
      margin: 0 !important;
      padding: 0 !important;
      border: none !important;
      background: transparent !important;
      box-sizing: border-box !important;
      visibility: visible !important;
      opacity: 1 !important;
    }
    
    /* Reset all inherited properties inside Shadow DOM */
    * {
      box-sizing: border-box !important;
    }
  `;
  shadow.appendChild(isolationStyle);

  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = cssUrl;

  const container = document.createElement("div");
  container.id = "ragsuite-search-widget-container";
  container.className = "ragsuite-search-widget-root ragsuite-search-scope";
  
  container.style.cssText = `
    width: 100% !important;
    height: 100% !important;
    display: block !important;
    position: relative !important;
    margin: 0 !important;
    padding: 24px !important;
    border: none !important;
    box-sizing: border-box !important;
    isolation: isolate !important;
    contain: layout style paint !important;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif !important;
    font-size: 16px !important;
    line-height: 1.5 !important;
    visibility: visible !important;
    opacity: 1 !important;
  `;
  
  container.setAttribute('data-ragsuite-widget-container', 'search');
  
  shadow.appendChild(container);
  
  (hostElement as any).__ragsuiteContainer = container;
  (window as any).__RAGSUITE_SEARCH_CONTAINER__ = container;

  const onReadyCallback = () => {
    const fallback = document.getElementById('ragsuite-widget-fallback');
    if (fallback) {
      fallback.remove();
    }
    window.dispatchEvent(new CustomEvent("ragsuite-search:ready"));
  };
  
  const onErrorCallback = (error: any) => {
    console.error("RAG Suite Search Widget: Error occurred", error);
    window.dispatchEvent(
      new CustomEvent("ragsuite-search:error", { detail: error })
    );
  };
  
  const SearchWidgetWrapper = React.memo(() => {
    const [isOpen] = React.useState(true);
    const { theme } = useTheme();
    const containerRef = React.useRef<HTMLElement | null>(null);
    
    const { isActive: isSearchActive, isLoading: isActivationLoading, activationData } = useSearchActivation();
    
    React.useEffect(() => {
      if ((window as any).__RAGSUITE_SEARCH_CONTAINER__) {
        containerRef.current = (window as any).__RAGSUITE_SEARCH_CONTAINER__;
      } else {
        const host = document.getElementById('ragsuite-search-widget-host');
        if (host?.shadowRoot) {
          const container = host.shadowRoot.getElementById('ragsuite-search-widget-container');
          if (container) {
            containerRef.current = container;
          }
        }
      }
      
      if (!containerRef.current) {
        console.warn('⚠️ Widget container not found - trying alternative method');
        const host = document.getElementById('ragsuite-search-widget-host');
        if ((host as any)?.__ragsuiteContainer) {
          containerRef.current = (host as any).__ragsuiteContainer;
        }
      }
    }, []);
    
    React.useEffect(() => {
      if (containerRef.current) {
        containerRef.current.classList.remove('light', 'dark');
        containerRef.current.classList.add(theme);
        containerRef.current.setAttribute('data-theme', theme);
        
      }
    }, [theme]);

    const handleToggle = React.useCallback(() => {
    }, []);
    
    const instanceProjectId = searchWidgetInstance?.projectId || 
      (window as any).RAGSUITE_PROJECT_ID;
    
    const isWidgetMode = typeof window !== 'undefined' && !!instanceProjectId;
    
    React.useEffect(() => {
      if (!containerRef.current) {
        console.warn('⚠️ Container ref not available yet');
        return;
      }
      
        if (isWidgetMode) {
        containerRef.current.style.display = 'block';
        containerRef.current.style.visibility = 'visible';
        containerRef.current.style.opacity = '1';
        containerRef.current.style.pointerEvents = 'auto';
        containerRef.current.style.minHeight = '100px';
        containerRef.current.style.width = '100%';
        } else if (!isSearchActive && !isActivationLoading) {
        containerRef.current.style.display = 'none';
        containerRef.current.style.visibility = 'hidden';
        containerRef.current.style.opacity = '0';
        containerRef.current.style.pointerEvents = 'none';
        } else if (isSearchActive) {
        containerRef.current.style.display = 'block';
        containerRef.current.style.visibility = 'visible';
        containerRef.current.style.opacity = '1';
        containerRef.current.style.pointerEvents = 'auto';
      }
    }, [isSearchActive, isActivationLoading, activationData, isWidgetMode]);
    
    if (isWidgetMode) {
      React.useEffect(() => {
        const fallback = document.getElementById('ragsuite-widget-fallback');
        if (fallback) {
          fallback.remove();
        }
      }, []);
      
      return (
        <EmbeddableSearchWidget
          isOpen={isOpen}
          onToggle={handleToggle}
          onReady={onReadyCallback}
          onError={onErrorCallback}
        />
      );
    }
    
    if (!isSearchActive) {
      return null;
    }
    
    if (isActivationLoading && activationData === undefined) {
      return null;
    }
    
    return (
      <EmbeddableSearchWidget
        isOpen={isOpen}
        onToggle={handleToggle}
        onReady={onReadyCallback}
        onError={onErrorCallback}
      />
    );
  });
  
  let root: ReturnType<typeof createRoot> | null = null;
  let hasMounted = false;
  const mountWidgetApp = () => {
    if (hasMounted) return;
    hasMounted = true;

    try {
      root = createRoot(container);
      root.render(
        <QueryClientProvider client={searchWidgetQueryClient}>
          <AuthProvider>
            <RAGSettingsProvider>
              <BrandingProvider>
                <ThemeProvider>
                  <CitationFormattingProvider>
                    <SearchWidgetWrapper />
                  </CitationFormattingProvider>
                </ThemeProvider>
              </BrandingProvider>
            </RAGSettingsProvider>
          </AuthProvider>
        </QueryClientProvider>
      );
    } catch (error) {
      console.error('❌ Error rendering React root:', error);
      const fallback = document.getElementById('ragsuite-widget-fallback');
      if (fallback) {
        const h3 = document.createElement('h3');
        h3.style.cssText = 'margin:0 0 10px 0; color:red;';
        h3.textContent = 'Error Loading Widget';
        const p = document.createElement('p');
        p.style.cssText = 'margin:0; color:#666;';
        p.textContent = (error as Error).message;
        fallback.appendChild(h3);
        fallback.appendChild(p);
      }
    }

    searchWidgetInstance = { root, container, projectId: config.projectId };
    if (exclusive) {
      registry.search = { priority, destroy: destroySearchWidget };
    }
    (window as any).RAGSUITE_API_URL = API_BASE_URL;
  };

  link.onload = () => {
    mountWidgetApp();
  };
  link.onerror = () => {
    console.warn("⚠️ RAG Suite Search Widget: Failed to load CSS from", cssUrl);
    mountWidgetApp();
  };
  shadow.appendChild(link);

  window.setTimeout(() => {
    mountWidgetApp();
  }, 1200);
}

function destroySearchWidget() {
  if (searchWidgetInstance) {
    searchWidgetInstance.root?.unmount?.();
    searchWidgetInstance.container.remove();
    searchWidgetInstance = null;
    window.dispatchEvent(new CustomEvent("ragsuite-search:destroyed"));

    const registry = getRegistry();
    if (registry.search?.destroy === destroySearchWidget) {
      delete registry.search;
    }
    
    Object.keys(window).forEach(key => {
      if (key.startsWith('__RAGSUITE_INIT_EXECUTED_')) {
        try {
          delete (window as any)[key];
        } catch (e) {
        }
      }
    });
    
    if ((window as any).RAGSUITE_PROJECT_ID) {
      delete (window as any).RAGSUITE_PROJECT_ID;
    }
  }
}

declare global {
  interface Window {
    RAGSuiteSearchWidget: {
      init: (config: SearchWidgetConfig) => void;
      destroy: () => void;
      version: string;
    };
  }
}

window.RAGSuiteSearchWidget = {
  init: initSearchWidget,
  destroy: destroySearchWidget,
  version: "1.0.0",
};
