import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { searchAPI, compareAPI, SearchResponse } from '@/services/api/api';
import { invalidateFeedbackModeration } from '@/services/api/feedbackModeration';
import type { CompareSearchRequest, CompareSearchResponse } from '@/services/api/types';
import { useProjects } from './useProjects';

export const useSearch = () => {
  const searchMutation = useMutation({
    mutationFn: ({ query, ragSettings, responseType }: {
      query: string;
      ragSettings?: {
        topK?: number;
        similarityThreshold?: number;
        useReranker?: boolean;
        maxTokens?: number;
      };
      responseType?: 'long' | 'short';
    }) => searchAPI.search(query, ragSettings, responseType),

    onSuccess: (data: SearchResponse) => {
    },

    onError: (error) => {
      console.error('❌ Search failed:', error);
    },
  });

  return {
    search: (query: string, ragSettings?: any, responseType?: 'long' | 'short') => searchMutation.mutate({ query, ragSettings, responseType }),
    searchAsync: (query: string, ragSettings?: any, responseType?: 'long' | 'short') => searchMutation.mutateAsync({ query, ragSettings, responseType }),
    isSearching: searchMutation.isPending,
    searchData: searchMutation.data,
    searchError: searchMutation.error,
    reset: searchMutation.reset,
  };
};

export const useCompareSearch = () => {
  const { activeProjectId } = useProjects();
  const mutation = useMutation({
    mutationFn: (payload: CompareSearchRequest) => compareAPI.compareSearch(payload),
    onError: (error) => {
      console.error('❌ Compare search failed:', error);
    },
  });

  const profilesQuery = useQuery({
    queryKey: ['model-profiles', activeProjectId || 'no-project'],
    queryFn: () => compareAPI.getModelProfiles(),
    enabled: !!activeProjectId,
  });

  const profilesList = profilesQuery.data?.profiles ?? [];

  return {
    compare: mutation.mutate,
    compareAsync: mutation.mutateAsync,
    isComparing: mutation.isPending,
    compareData: mutation.data,
    compareError: mutation.error,
    resetCompare: mutation.reset,
    profiles: profilesList,
    compareConfiguredSource: profilesQuery.data?.configured_source ?? 'search',
    compareEffectiveSource: profilesQuery.data?.effective_source ?? 'search',
    profilesLoading: profilesQuery.isLoading,
    refetchProfiles: profilesQuery.refetch,
    updateModelProfile: compareAPI.updateModelProfile,
    deleteModelProfile: compareAPI.deleteModelProfile,
    createModelProfile: compareAPI.createModelProfile,
    compareStream: compareAPI.compareSearchStream,
  };
};

export const useSearchFeedback = () => {
  const queryClient = useQueryClient();

  const feedbackMutation = useMutation({
    mutationFn: ({
      sessionId,
      messageId,
      feedback,
      rating,
      feedback_text,
      context_tags
    }: {
      sessionId: string;
      messageId: string;
      feedback: 'positive' | 'negative';
      rating?: number;
      feedback_text?: string;
      context_tags?: string[];
    }) =>
      searchAPI.submitFeedback(sessionId, messageId, feedback, rating, feedback_text, context_tags),

    onSuccess: (data) => {
      if (data && typeof data === "object" && (data as { success?: boolean }).success === false) {
        return;
      }
      invalidateFeedbackModeration(queryClient);
    },

    onError: (error) => {
      console.error('❌ Search feedback submission failed:', error);
    },
  });

  return {
    submitFeedback: feedbackMutation.mutate,
    isSubmitting: feedbackMutation.isPending,
    feedbackData: feedbackMutation.data,
    feedbackError: feedbackMutation.error,
  };
};
