import { ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { useTheme } from '@/contexts/ThemeContext';

interface GlassCardProps {
  children: ReactNode;
  className?: string;
  variant?: 'light' | 'dark' | 'auto';
  noHover?: boolean;
  onClick?: () => void;
  [key: string]: any;
}

export function GlassCard({ 
  children, 
  className = "",
  variant = 'auto',
  noHover = false,
  onClick,
  ...props
}: GlassCardProps) {
  const { theme } = useTheme();
  
  const getVariant = () => {
    if (variant === 'auto') {
      return theme === 'dark' ? 'dark' : 'light';
    }
    return variant;
  };

  const currentVariant = getVariant();

  return (
    <div 
      className={cn(
        "border transition-all duration-300",
        currentVariant === 'dark' 
          ? "glass-card-dark text-white" 
          : "bg-white text-foreground border-border",
        className
      )}
      style={{
        borderRadius: 'var(--component-cardRadius, 2px)',
        ...(currentVariant === 'dark'
          ? { backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)', boxShadow: '0px 1px 5px -1px rgba(0, 0, 0, 0.2)' }
          : { boxShadow: 'none' })
      }}
      onClick={onClick}
      {...props}
    >
      {children}
    </div>
  );
}
