import { apiClient, API_BASE_URL } from "@/services/api/client";
import { documentAPI } from "@/services/api/api";
import { getWidgetAssetOrigin, resolveBrowserApiBaseUrl } from "@/utils/publicApiBaseUrl";

/** Paths like /api/v1/documents/{uuid}/content or /content-stream */
const DOCUMENT_CONTENT_RE =
  /\/documents\/([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\/content(?:-stream)?(?:\?|#|$)/i;

export function isAuthenticatedDocumentContentUrl(url: string): boolean {
  if (!url || url === "#") return false;
  return DOCUMENT_CONTENT_RE.test(url.trim());
}

function buildContentStreamUrl(documentId: string, token: string): string {
  const resolvedApiBase = resolveBrowserApiBaseUrl(
    typeof window !== "undefined" && (window as any).RAGSUITE_API_URL
      ? String((window as any).RAGSUITE_API_URL)
      : API_BASE_URL,
    {
      pageOrigin: typeof window !== "undefined" ? window.location.origin : "",
      assetOrigin: getWidgetAssetOrigin(),
    },
  );
  return `${resolvedApiBase}/documents/${documentId}/content-stream?token=${encodeURIComponent(token)}`;
}

function openUrlInNewTab(url: string, existingTab?: Window | null): void {
  if (existingTab && !existingTab.closed) {
    existingTab.location.href = url;
    return;
  }
  const win = window.open(url, "_blank", "noopener,noreferrer");
  if (!win) {
    const a = document.createElement("a");
    a.href = url;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
}

/**
 * Opens a citation URL.
 * For document content paths: uses a short-lived token + /content-stream so the
 * browser streams the file natively (no full blob download before opening).
 * Falls back to blob download if token fetch fails.
 */
export async function openCitationSourceUrl(url: string): Promise<void> {
  const trimmed = url.trim();
  const m = trimmed.match(DOCUMENT_CONTENT_RE);
  if (m) {
    const documentId = m[1];

    // Open a tab synchronously (while still in the click handler) so popup blockers allow it.
    const pendingTab = window.open("about:blank", "_blank");

    // Preferred path: tokenized stream — browser loads progressively instead of waiting for full blob.
    try {
      const token = await documentAPI.getDocumentContentToken(documentId);
      const streamUrl = buildContentStreamUrl(documentId, token);
      openUrlInNewTab(streamUrl, pendingTab);
      return;
    } catch {
      pendingTab?.close();
    }

    // Fallback: authenticated content endpoint (works when token endpoint is unavailable).
    try {
      const response = await apiClient.get(`/documents/${documentId}/content`, {
        responseType: "blob",
      });
      const streamBlob =
        response.data instanceof Blob
          ? response.data
          : new Blob([response.data], {
              type: String(response.headers?.["content-type"] || "application/octet-stream"),
            });
      const blobType = (streamBlob.type || "").toLowerCase();
      if (blobType.includes("text/html")) {
        throw new Error("content endpoint returned HTML instead of document bytes");
      }
      const streamBlobUrl = URL.createObjectURL(streamBlob);
      openUrlInNewTab(streamBlobUrl);
      window.setTimeout(() => URL.revokeObjectURL(streamBlobUrl), 120_000);
      return;
    } catch {
      throw new Error("Could not open source document.");
    }
  }
  window.open(trimmed, "_blank", "noopener,noreferrer");
}
