const DEV_FRONTEND_PORTS = new Set(["3000", "5173", "5174", "6173"]);
const DEFAULT_API_PATH = "/api/v1";
const DEV_BACKEND_PORT = "8000";

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, "");
}

function isPrivateOrLoopbackHostname(hostname: string): boolean {
  const host = String(hostname || "").toLowerCase().trim();
  if (!host) return false;
  if (host === "localhost" || host === "127.0.0.1" || host === "0.0.0.0" || host === "::1") {
    return true;
  }
  if (/^192\.168\.\d+\.\d+$/.test(host)) return true;
  if (/^10\.\d+\.\d+\.\d+$/.test(host)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/.test(host)) return true;
  return false;
}

function coerceDevFrontendPort(url: URL): URL {
  if (!DEV_FRONTEND_PORTS.has(url.port || "")) {
    return url;
  }
  const next = new URL(url.toString());
  next.port = DEV_BACKEND_PORT;
  if (!next.pathname || next.pathname === "/") {
    next.pathname = DEFAULT_API_PATH;
  }
  return next;
}

function toAbsoluteUrl(raw: string, fallbackOrigin: string): URL | null {
  try {
    return new URL(raw, fallbackOrigin);
  } catch {
    return null;
  }
}

export function resolveBrowserApiBaseUrl(
  rawCandidate?: string | null,
  options?: {
    pageOrigin?: string | null;
    assetOrigin?: string | null;
    defaultPath?: string;
  },
): string {
  const pageOrigin =
    options?.pageOrigin ||
    (typeof window !== "undefined" ? window.location.origin : "");
  const assetOrigin = options?.assetOrigin || pageOrigin;
  const defaultPath = options?.defaultPath || DEFAULT_API_PATH;
  const fallbackOrigin = assetOrigin || pageOrigin || "http://localhost";
  const fallbackUrl = `${trimTrailingSlash(fallbackOrigin)}${defaultPath}`;
  const candidate = String(rawCandidate || "").trim() || fallbackUrl;

  let resolved = toAbsoluteUrl(candidate, fallbackOrigin);
  if (!resolved) {
    return fallbackUrl;
  }

  resolved = coerceDevFrontendPort(resolved);

  const preferredOriginUrl =
    toAbsoluteUrl(assetOrigin || "", fallbackOrigin) ||
    toAbsoluteUrl(pageOrigin || "", fallbackOrigin);
  const currentPageUrl = toAbsoluteUrl(pageOrigin || "", fallbackOrigin);

  const candidateLooksPrivate =
    isPrivateOrLoopbackHostname(resolved.hostname) || DEV_FRONTEND_PORTS.has(resolved.port || "");
  const preferredLooksPublic =
    !!preferredOriginUrl &&
    !isPrivateOrLoopbackHostname(preferredOriginUrl.hostname) &&
    !DEV_FRONTEND_PORTS.has(preferredOriginUrl.port || "");

  if (candidateLooksPrivate && preferredLooksPublic && preferredOriginUrl) {
    resolved = new URL(resolved.pathname || defaultPath, preferredOriginUrl.origin);
    if (!resolved.pathname || resolved.pathname === "/") {
      resolved.pathname = defaultPath;
    }
  }

  if (
    currentPageUrl?.protocol === "https:" &&
    resolved.protocol === "http:" &&
    preferredOriginUrl?.protocol === "https:"
  ) {
    resolved = new URL(resolved.pathname || defaultPath, preferredOriginUrl.origin);
    if (!resolved.pathname || resolved.pathname === "/") {
      resolved.pathname = defaultPath;
    }
  }

  return trimTrailingSlash(resolved.toString());
}

export function getWidgetAssetOrigin(): string | null {
  if (typeof window === "undefined") return null;
  const value =
    (window as any).RAGSUITE_ASSET_ORIGIN ||
    (window as any).RAGSUITE_SEARCH_WIDGET_ASSET_ORIGIN ||
    null;
  return typeof value === "string" && value.trim() ? trimTrailingSlash(value) : null;
}
