export type SearchResponseLayout = "long" | "short";

export function isShortSearchAnswerContent(content: string): boolean {
  const trimmed = (content || "").trim();
  if (!trimmed) return false;
  if (/<h[1-6][\s>]/i.test(trimmed)) return false;
  if (/<ul[\s>]/i.test(trimmed) || /<ol[\s>]/i.test(trimmed)) return false;
  return trimmed.length < 700;
}

export function resolveSearchAnswerLayout(
  responseType?: SearchResponseLayout | null,
  content?: string,
): SearchResponseLayout {
  if (responseType === "short" || responseType === "long") {
    return responseType;
  }
  return isShortSearchAnswerContent(content || "") ? "short" : "long";
}

const PROSE_BASE =
  "prose prose-sm dark:prose-invert max-w-none w-full min-w-0 prose-headings:text-foreground prose-p:text-foreground prose-strong:text-foreground prose-code:text-foreground prose-pre:bg-muted prose-pre:text-foreground prose-blockquote:text-muted-foreground prose-blockquote:border-l-muted-foreground prose-p:break-words prose-p:overflow-wrap-anywhere prose-headings:break-words prose-headings:overflow-wrap-anywhere prose-li:break-words prose-li:overflow-wrap-anywhere";

export function getSearchAnswerProseClass(layout: SearchResponseLayout): string {
  if (layout === "short") {
    return `${PROSE_BASE} prose-p:my-0 prose-p:leading-relaxed text-[0.9375rem]`;
  }
  return PROSE_BASE;
}

export function getSearchResultStackClass(layout: SearchResponseLayout): string {
  return layout === "short"
    ? "space-y-2 w-full min-w-0 max-w-full overflow-x-hidden"
    : "space-y-4 w-full min-w-0 max-w-full overflow-x-hidden";
}

export function getSearchCitationListClass(layout: SearchResponseLayout): string {
  return "pt-4 border-t border-border space-y-3 w-full min-w-0";
}

export function getSearchActionsRowClass(layout: SearchResponseLayout): string {
  return layout === "short"
    ? "flex items-center gap-2 pt-2"
    : "flex items-center justify-between gap-2 pt-3 mt-3 border-t border-border/20";
}
